css:
.fx-art{position:relative;overflow:hidden;background:linear-gradient(135deg,var(--primary),color-mix(in srgb,var(--primary) 45%,var(--accent)))}
.fx-art::before,.fx-art::after{content:"";position:absolute;border-radius:50%;background:color-mix(in srgb,var(--accent) 60%,#fff);opacity:.35}
.fx-art::before{width:60%;aspect-ratio:1;right:-12%;top:-20%}.fx-art::after{width:38%;aspect-ratio:1;left:8%;bottom:-18%;opacity:.25;background:#fff}
.fx-art.a2{background:linear-gradient(160deg,var(--accent),color-mix(in srgb,var(--accent) 40%,var(--primary)))}
.fx-art.a3{background:linear-gradient(200deg,color-mix(in srgb,var(--primary) 70%,#000),var(--accent))}
.fx-lb{width:min(1000px,100%);display:grid;gap:1.6em}
.fx-lb h2{font-size:clamp(1.8em,4vw,2.6em)}.fx-lb .hint{opacity:.55;font-size:.88em}
.fx-lb .grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));grid-auto-rows:11em;gap:1em}
.fx-lb .th{all:unset;box-sizing:border-box;position:relative;overflow:hidden;border-radius:var(--radius);cursor:zoom-in;isolation:isolate}
.fx-lb .th:first-child{grid-column:span 2}
.fx-lb .th .fx-art{position:absolute;inset:0;transition:transform calc(.6s/var(--speed)) cubic-bezier(.2,.8,.2,1)}
.fx-lb .th::after{content:"+";position:absolute;right:.7em;top:.7em;width:2em;height:2em;display:grid;place-items:center;border-radius:50%;background:var(--surface);color:var(--text);font-weight:700;opacity:0;transform:scale(.7);transition:opacity .3s,transform .3s}
.fx-lb .th:hover .fx-art{transform:scale(1.06)}.fx-lb .th:hover::after,.fx-lb .th:focus-visible::after{opacity:1;transform:none}
.fx-lb .th:focus-visible{outline:2px solid var(--accent);outline-offset:3px}
.fx-lb .lb{position:fixed;inset:0;z-index:50;display:grid;place-items:center;opacity:0;visibility:hidden;transition:opacity calc(.3s/var(--speed)),visibility 0s calc(.3s/var(--speed))}
.fx-lb .lb.on{opacity:1;visibility:visible;transition-delay:0s}
.fx-lb .bd{position:absolute;inset:0;background:rgba(10,12,18,.9)}
.fx-lb .fig{position:relative;margin:0;display:grid;gap:.8em;transform:scale(.96);transition:transform calc(.4s/var(--speed)) cubic-bezier(.2,.8,.2,1)}
.fx-lb .lb.on .fig{transform:none}
.fx-lb .fig .fx-art{width:min(88vw,calc(62vh*1.5),60em);aspect-ratio:3/2;border-radius:calc(var(--radius)*.7)}
.fx-lb figcaption{display:flex;justify-content:space-between;color:#fff;font-size:.9em;opacity:.85}
.fx-lb .lb button{all:unset;box-sizing:border-box;position:absolute;width:2.8em;height:2.8em;border-radius:50%;display:grid;place-items:center;background:rgba(255,255,255,.12);color:#fff;cursor:pointer;font-size:1em;transition:background .25s}
.fx-lb .lb button:hover{background:rgba(255,255,255,.26)}.fx-lb .lb button:focus-visible{outline:2px solid #fff;outline-offset:2px}
.fx-lb .lb button.x{top:1em;right:1em}.fx-lb .lb button.pv{left:1em;top:50%;margin-top:-1.4em}.fx-lb .lb button.nx{right:1em;top:50%;margin-top:-1.4em}
@media(max-width:600px){.fx-lb .grid{grid-template-columns:repeat(2,minmax(0,1fr));grid-auto-rows:9em}.fx-lb .lb button.pv,.fx-lb .lb button.nx{top:auto;bottom:1em;margin:0}.fx-lb .lb button.pv{left:calc(50% - 3.4em)}.fx-lb .lb button.nx{right:calc(50% - 3.4em)}}
@media(prefers-reduced-motion:reduce){.fx-lb .lb,.fx-lb .fig,.fx-lb .th .fx-art{transition:none}}
/* touch: :hover mirrored as .is-tap */
.fx-lb .th.is-tap .fx-art{transform:scale(1.06)}
.fx-lb .th.is-tap::after{opacity:1;transform:none}
.fx-lb .lb button.is-tap{background:rgba(255,255,255,.26)}

js:
(function(){document.querySelectorAll('.fx-lb').forEach(function(r){
var th=[].slice.call(r.querySelectorAll('.th')),lb=r.querySelector('.lb'),art=lb.querySelector('.fx-art'),cp=lb.querySelector('.cp'),ct=lb.querySelector('.ct'),i=0,last=null;
var btns=[].slice.call(lb.querySelectorAll('button'));
function show(n){i=(n+th.length)%th.length;var t=th[i];art.className='fx-art '+(t.getAttribute('data-v')||'');cp.textContent=t.getAttribute('data-t');ct.textContent=(i+1)+' / '+th.length}
function open(n){last=document.activeElement;show(n);lb.classList.add('on');lb.setAttribute('aria-hidden','false');btns[0].focus()}
function close(){lb.classList.remove('on');lb.setAttribute('aria-hidden','true');if(last)last.focus()}
th.forEach(function(t,k){t.addEventListener('click',function(){open(k)})});
lb.querySelector('.bd').addEventListener('click',close);btns[0].addEventListener('click',close);
lb.querySelector('.pv').addEventListener('click',function(){show(i-1)});lb.querySelector('.nx').addEventListener('click',function(){show(i+1)});
lb.addEventListener('keydown',function(e){if(e.key==='Escape')close();else if(e.key==='ArrowLeft')show(i-1);else if(e.key==='ArrowRight')show(i+1);
else if(e.key==='Tab'){var f=btns[0],l=btns[btns.length-1];if(e.shiftKey&&document.activeElement===f){e.preventDefault();l.focus()}else if(!e.shiftKey&&document.activeElement===l){e.preventDefault();f.focus()}}});
})})();
/* fx-touch */
(function(){if(window.__fxTap)return;window.__fxTap=1;var cur=[];function clr(){cur.forEach(function(e){e.classList.remove('is-tap')});cur=[]}
document.addEventListener('pointerdown',function(e){if(e.pointerType!=='touch')return;clr();var n=e.target.closest&&e.target.closest('.fx');if(!n)return;for(var el=e.target;el&&el!==n.parentNode;el=el.parentNode){if(el.classList){el.classList.add('is-tap');cur.push(el)}}},{passive:true});
document.addEventListener('pointerup',function(){setTimeout(clr,1400)},{passive:true})})();
